parameters.jsCode:
const input = $('Webhook').item.json.body.plan.location;

let coordinates;

// Case 1: String with coordinates
if (typeof input === 'string') {
  const match = input.match(/x:\s*(-?\d+\.?\d*),\s*y:\s*(-?\d+\.?\d*),\s*z:\s*(-?\d+\.?\d*)/);
  if (match) {
    coordinates = {
      x: Math.floor(parseFloat(match[1])),
      y: Math.floor(parseFloat(match[2])),
      z: Math.floor(parseFloat(match[3]))
    };
  }
}
// Case 2: Object with coordinates
else if (typeof input === 'object' && input !== null) {
  coordinates = {
    x: Math.floor(input.x),
    y: Math.floor(input.y),
    z: Math.floor(input.z)
  };
}

return coordinates || null;

// Extract stages directly from Planner output
// No more coordinate replacement or dynamic division needed

const plan = $('Webhook').first().json.body.plan;

// Validate plan came back successfully
if (!plan || !plan.stages) {
  throw new Error('No valid plan received from Planner');
}

// Extract stages directly (already complete from planner)
const stages = plan.stages;
const totalStages = plan.metadata.totalStages;

console.log(`✅ Plan validated and ready`);
console.log(`Total stages: ${totalStages}`);
console.log(`Stages: ${Object.keys(stages).join(', ')}`);

// Optional: Minimal transformation if needed
// (e.g., convert stage format or add metadata)
const processedStages = {};
Object.entries(stages).forEach(([stageKey, stageData]) => {
  processedStages[stageKey] = {
    ...stageData,
    startTime: null,
    completedCount: 0
  };
});

return {
  stages: processedStages,
  totalStages: totalStages,
  metadata: plan.metadata,
  buildingRequest: plan.buildingRequest,
  coordinationStrategy: plan.coordinationStrategy,
  status: 'ready'
};

const stage = $('Loop Over Stages').item.json;

if (!stage.stageNumber) {
  throw new Error('❌ Input must be a stage object with stageNumber');
}

// Get spawned workers from the spawnedWorkers node
let spawnedWorkers = [];
try {
  const spawnedData = $('SpawnWorkers').item;
  if (spawnedData && spawnedData.json && spawnedData.json.spawnedWorkers) {
    spawnedWorkers = spawnedData.json.spawnedWorkers;
  }
} catch (e) {
  console.warn('⚠️  Could not retrieve spawned workers, using stage worker names');
}

if (spawnedWorkers.length === 0) {
  throw new Error('❌ No spawned workers found. Ensure spawnedWorkers node has output.');
}

// Access tasks from stage.tasks instead of stage directly
const tasks = stage.tasks || {};
const workerPattern = /^Worker\d+$/;
const workerKeys = Object.keys(tasks).filter(key => workerPattern.test(key));

if (workerKeys.length === 0) {
  throw new Error('❌ Stage must have at least one Worker (Worker1, Worker2, etc.)');
}

// Sort workers by number (Worker1, Worker2, Worker3...)
workerKeys.sort((a, b) => {
  const numA = parseInt(a.replace('Worker', ''));
  const numB = parseInt(b.replace('Worker', ''));
  return numA - numB;
});

// Validate we have matching number of spawned workers
if (workerKeys.length > spawnedWorkers.length) {
  throw new Error(
    `❌ Stage has ${workerKeys.length} workers but only ${spawnedWorkers.length} spawned workers available`
  );
}

// Build worker execution items using actual spawned worker info
const workerItems = [];

for (let i = 0; i < workerKeys.length; i++) {
  const workerKey = workerKeys[i];
  const workerData = tasks[workerKey];
  const spawnedWorker = spawnedWorkers[i];

  // Validate worker has required fields
  if (!workerData) {
    throw new Error(`❌ ${workerKey} data is missing`);
  }

  if (!workerData.fullPrompt) {
    throw new Error(`❌ ${workerKey} missing required field: fullPrompt`);
  }

  // Build execution item with actual spawned worker info
  const executionItem = {
    stageNumber: stage.stageNumber,
    stageTitle: stage.stageTitle,
    workerIndex: i + 1,
    workerName: spawnedWorker.workerName,
    port: spawnedWorker.port,
    ready: spawnedWorker.ready,
    commands: workerData.commands,
    objective: workerData.objective || '',
    subtask: workerData.subtask || '',
    coordinates: workerData.coordinates || {},
    constraints: workerData.constraints || [],
    parallelExecution: stage.parallelExecution || false,
    status: workerData.status || 'not-started'
  };

  workerItems.push(executionItem);
}

console.log(`✅ Stage ${stage.stageNumber} (${stage.stageTitle}) mapped to ${workerItems.length} spawned workers`);
for (const item of workerItems) {
  console.log(`   ${item.workerName} (port ${item.port}): ${item.subtask}`);
}

return {tasks: workerItems}

// Get stage number from current loop item
const currentStage = $('Loop Over Stages').item.json.stageNumber;
const previousStage = currentStage - 1;
const sessionId = $input.item.json.sessionId;

if (currentStage === 1) {
  return {
    sessionId: sessionId,
    stageNumber: 1, 
    canProceed: true,
    reason: "First stage"
  };
}

// Now get the document (must come from previous MongoDB read or Set node)
const doc = $input.item.json;

if (!doc.stages || !doc.stages?.[previousStage]) {
  return {
    stageNumber: currentStage,
    canProceed: false,
    reason: `Stage ${previousStage} not found`
  };
}

const previousStageData = doc.stages?.[previousStage];
const workers = Object.keys(previousStageData.tasks);

//const allComplete = workers.every(w => 
//  previousStageData.tasks[w].status === "completed"
//);
const allComplete = previousStageData.status === "completed";

return {
  sessionId: sessionId,
  canProceed: allComplete,
  previousStage: previousStage,
  stageNumber: currentStage,
  completedWorkers: workers.filter(w => previousStageData.tasks[w].status === "completed").length,
  totalWorkers: workers.length
};
